// Initialize PocketBase collections and seed data
async function initializeDatabase() {
  log('info', 'Initializing database...');

  // Seed demo user
  const demoEmail = 'demo@ethara.ai';
  const demoPassword = 'deku-demo-pw-2026';

  let demoUser;
  let demoPb = new PocketBase(BACKEND_URL);

  // Try to login first
  try {
    const authData = await demoPb.collection('users').authWithPassword(demoEmail, demoPassword);
    demoUser = authData.record;
    log('info', 'Demo user logged in', { userId: demoUser.id });
  } catch (err) {
    // User doesn't exist, create it
    try {
      demoUser = await demoPb.collection('users').create({
        email: demoEmail,
        password: demoPassword,
        passwordConfirm: demoPassword,
        emailVisibility: true
      });
      log('info', 'Demo user created', { userId: demoUser.id });

      // Now login
      const authData = await demoPb.collection('users').authWithPassword(demoEmail, demoPassword);
      demoUser = authData.record;
    } catch (createErr) {
      log('error', 'Failed to create demo user', { error: createErr.message });
      return;
    }
  }

  // Seed habits
  const habitSeeds = [
    { name: 'Meditate', color: 'indigo' },
    { name: 'Read 20 minutes', color: 'teal' },
    { name: 'No soda', color: 'amber' }
  ];

  const habits = {};

  for (const seed of habitSeeds) {
    try {
      const existing = await demoPb.collection('habits').getFullList({
        filter: `user_id = "${demoUser.id}" && name = "${seed.name}"`
      });

      if (existing.length > 0) {
        habits[seed.name] = existing[0];
        log('info', 'Habit exists', { name: seed.name });
      } else {
        const habit = await demoPb.collection('habits').create({
          user_id: demoUser.id,
          name: seed.name,
          color: seed.color,
          description: '',
          deleted: false
        });
        habits[seed.name] = habit;
        log('info', 'Habit created', { name: seed.name, habitId: habit.id });
      }
    } catch (err) {
      log('error', 'Failed to create habit', { name: seed.name, error: err.message });
    }
  }

  // Seed completions
  // Meditate: current_streak of 5 (today and 4 preceding days)
  // Read 20 minutes: current_streak of 0, longest_streak of at least 3 (3 days earlier this month)
  // No soda: current_streak of 1 (today only, gap yesterday)

  const getDateOffset = (offset) => {
    const d = new Date();
    d.setDate(d.getDate() + offset);
    return d.toISOString().split('T')[0];
  };

  const completionSeeds = [];

  // Meditate: today and 4 preceding days
  if (habits['Meditate']) {
    for (let i = 0; i >= -4; i--) {
      completionSeeds.push({ habit: habits['Meditate'], date: getDateOffset(i) });
    }
  }

  // Read 20 minutes: 3 consecutive days earlier this month (e.g., 10-12 days ago)
  if (habits['Read 20 minutes']) {
    for (let i = -10; i >= -12; i--) {
      completionSeeds.push({ habit: habits['Read 20 minutes'], date: getDateOffset(i) });
    }
  }

  // No soda: today only (gap yesterday)
  if (habits['No soda']) {
    completionSeeds.push({ habit: habits['No soda'], date: getDateOffset(0) });
  }

  for (const seed of completionSeeds) {
    try {
      const existing = await demoPb.collection('completions').getFullList({
        filter: `habit_id = "${seed.habit.id}" && date = "${seed.date}"`
      });

      if (existing.length === 0) {
        await demoPb.collection('completions').create({
          user_id: demoUser.id,
          habit_id: seed.habit.id,
          date: seed.date
        });
        log('info', 'Completion created', { habitName: seed.habit.name, date: seed.date });
      }
    } catch (err) {
      log('error', 'Failed to create completion', { habitName: seed.habit.name, date: seed.date, error: err.message });
    }
  }

  log('info', 'Database initialization complete');
}

